    # Perfis que já existem ganham a conciliação na mesma medida do que têm em Contas a pagar: quem vê as contas vê a
    # conciliação; quem paga (dá baixa) pode conciliar. O Administrador já pode tudo.
    import json

    conn = op.get_bind()
    perfis = sa.table("perfil_acesso", sa.column("id", sa.Integer), sa.column("permissoes", sa.JSON))
    for pid, permissoes in conn.execute(sa.select(perfis.c.id, perfis.c.permissoes)).all():
        atuais = json.loads(permissoes) if isinstance(permissoes, str) else list(permissoes or [])
        novas = [nova for tem, nova in (("contas_pagar.ver", "conciliacao.ver"), ("contas_pagar.pagar", "conciliacao.conciliar"))
                 if tem in atuais and nova not in atuais]
        if "conciliacao.conciliar" in novas and "conciliacao.ver" not in atuais + novas:
            novas.append("conciliacao.ver")
        if novas:
            conn.execute(perfis.update().where(perfis.c.id == pid).values(permissoes=sorted(atuais + novas)))


